2339	    // Clicks a menu row the way the platform's own pointer reaches it.
2340	    //
2341	    // Orca's PopupWindow installs a mouse re-dispatcher under __WXOSX__ only
2342	    // (Widgets/PopupWindow.hpp): there the popup receives the event and
2343	    // forwards it to the child under the pointer, so posting to the popup is
2344	    // what a real click does. Windows delivers to the child window directly
2345	    // and nothing forwards, so a click posted to the popup arrives nowhere and
2346	    // the row is never invoked -- the menu simply stays as it was, which reads
2347	    // as "the row did nothing" rather than as a broken click.
2348	    void click_row(HeaderMenu* menu, wxWindow* row)
2349	    {
2350	#ifdef __WXOSX__
2351	        wxWindow* target = menu;
2352	        const wxPoint at = row->GetPosition() + wxPoint(row->GetSize().x / 2, row->GetSize().y / 2);
2353	#else
2354	        wxWindow* target = row;
2355	        const wxPoint at(row->GetSize().x / 2, row->GetSize().y / 2);
2356	#endif
2357	        for (auto type : {wxEVT_LEFT_DOWN, wxEVT_LEFT_UP}) {
2358	            wxMouseEvent mouse(type);
2359	            mouse.SetPosition(at);
2360	            mouse.SetEventObject(target);
2361	            target->GetEventHandler()->ProcessEvent(mouse);
2362	        }
2363	    }
