39	    item.label = text;
40	    return item;
41	}
42	
43	wxString middot() { return wxString::FromUTF8(" \xC2\xB7 "); }
44	
45	// "Cold White · eSun" as one row label; the brand reads as secondary because
46	// the row paints everything after the separator in text/secondary would be a
47	// second text run. Keeping it in the label keeps ellipsis behaviour correct,
48	// and the brand is what gets dropped first when the name is long.
49	wxString spool_label(const Workspace::Spool& spool)
50	{
51	    wxString label = wxString::FromUTF8(spool.name);
52	    if (!spool.brand.empty()) label += middot() + wxString::FromUTF8(spool.brand);
53	    return label;
54	}
55	
56	bool matches(const SetupCommands::FilamentInfo& filament, const wxString& query)
57	{
58	    if (query.empty()) return true;
59	    const wxString needle = query.Lower();
60	    return filament.alias.Lower().Contains(needle) || filament.vendor.Lower().Contains(needle);
61	}
