69	void SpoolMenu::open(wxWindow* owner, const ShellTheme& theme, bool dark, Host host, HeaderButton& anchor)
70	{
71	    auto self = std::make_shared<SpoolMenu>(owner, theme, dark, std::move(host));
72	    self->m_anchor = &anchor;
73	    self->m_menu = new HeaderMenu(owner, theme, dark, {});
74	    show_spools(self);
75	    self->m_menu->open(anchor);
76	    // No dismiss listener: the row callbacks own the controller, so it is
77	    // released when the popup's rows are destroyed and any queued callback has
78	    // run -- never while one is still pending.
79	}
