81	void SpoolMenu::select(const Ptr& self, const Workspace::Spool& spool)
82	{
83	    Host& host = self->m_host;
84	    // Order matters: the preset switch first, because it can pull a colour of
85	    // its own from the preset, then the spool's colour over the top, then the
86	    // recency stamp. The chip refreshes from Orca's own settings-changed
87	    // notification, not from here.
88	    if (!SetupCommands::select_filament_preset(*host.plater, spool.filament_preset))
89	        return;
90	    const wxColour colour(wxString::FromUTF8(spool.colour));
91	    if (colour.IsOk())
92	        SetupCommands::set_filament_colour(*host.plater, colour);
93	    host.store->touch(spool.id);
94	    if (host.selected) host.selected(spool);
95	}
