104	void SpoolMenu::show_spools(const Ptr& self)
105	{
106	    auto* menu = self->m_menu.get();
107	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
108	    menu->set_header_builder(nullptr);
109	    const auto printer = SetupCommands::current_printer();
110	    const auto current = self->m_host.store->current(printer.preset_name,
111	                                               SetupCommands::current_filament().preset_name,
112	                                               SetupCommands::current_colour().ToStdString());
113	
114	    std::vector<HeaderMenuItem> rows;
115	    rows.push_back(title_row(wxString::Format(_L("SPOOLS ON %s"), printer.nickname.Upper())));
116	
117	    // Never truncated and never scrolled: a person keeps three to fifteen
118	    // spools, and the whole design rests on the right one being one click away.
119	    for (const Workspace::Spool& spool : self->m_host.store->spools_for(printer.preset_name)) {
120	        HeaderMenuItem row;
121	        row.label            = spool_label(spool);
122	        row.decoration.dot   = wxColour(wxString::FromUTF8(spool.colour));
123	        row.decoration.check = current.has_value() && current->id == spool.id;
124	        row.invoke           = [self, spool] { SpoolMenu::select(self, spool); };
125	        row.row_action       = HeaderIcon::More;
126	        row.invoke_row_action = [self, spool] { show_row_menu(self, spool); };
127	        rows.push_back(std::move(row));
128	    }
129	
130	    HeaderMenuItem other;
131	    other.separator          = true;
132	    other.label              = _L("Other spool…");
133	    other.decoration.trailing = HeaderIcon::Right;
134	    other.keeps_open         = true;
135	    other.invoke             = [self] { show_other_spool(self); };
136	    rows.push_back(std::move(other));
137	
138	    menu->replace_items(std::move(rows));
139	}
140	
141	void SpoolMenu::show_row_menu(const Ptr& self, const Workspace::Spool& spool)
142	{
143	    auto* menu = self->m_menu.get();
144	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
145	    menu->set_header_builder(nullptr);
146	    std::vector<HeaderMenuItem> rows;
147	
148	    HeaderMenuItem back;
149	    back.label      = wxString::FromUTF8(spool.name);
150	    back.icon       = HeaderIcon::Back;
151	    back.keeps_open = true;
152	    back.invoke     = [self] { show_spools(self); };
153	    rows.push_back(std::move(back));
154	    rows.push_back(separator());
155	
156	    HeaderMenuItem recolour;
157	    recolour.label      = _L("Change colour…");
158	    // NOT keeps_open. The system colour panel has no accept or cancel button
159	    // of its own on macOS, so its window frame is the only way out -- and a
160	    // transient popup renders above it and covers that frame. The popup has to
161	    // be gone before the dialog appears, or the person is trapped.
162	    recolour.invoke     = [self, spool] {
163	        wxColourData data;
164	        data.SetChooseFull(true);
165	        data.SetColour(wxColour(wxString::FromUTF8(spool.colour)));
166	        wxColourDialog dialog(self->m_owner, &data);
167	        dialog.CenterOnParent();
168	        if (dialog.ShowModal() != wxID_OK) { reopen(self); return; }
169	        const wxColour picked = dialog.GetColourData().GetColour();
170	        self->m_host.store->recolour(spool.id, picked.GetAsString(wxC2S_HTML_SYNTAX).ToStdString());
171	        // Recolouring the spool the project is on must move the project too,
172	        // or the chip would show a colour the print will not use.
173	        if (spool.filament_preset == SetupCommands::current_filament().preset_name &&
174	            spool.colour == SetupCommands::current_colour().ToStdString())
175	            SetupCommands::set_filament_colour(*self->m_host.plater, picked);
176	        if (self->m_host.store_changed) self->m_host.store_changed();
177	        reopen(self);
178	    };
179	    rows.push_back(std::move(recolour));
180	
181	    HeaderMenuItem rename;
182	    rename.label      = _L("Rename…");
183	    rename.invoke     = [self, spool] {
184	        wxTextEntryDialog dialog(self->m_owner, _L("Spool name"), _L("Rename spool"), wxString::FromUTF8(spool.name));
185	        if (dialog.ShowModal() == wxID_OK && !dialog.GetValue().Trim().empty()) {
186	            self->m_host.store->rename(spool.id, dialog.GetValue().Trim().ToStdString());
187	            if (self->m_host.store_changed) self->m_host.store_changed();
188	        }
189	        reopen(self);
190	    };
191	    rows.push_back(std::move(rename));
192	    rows.push_back(separator());
193	
194	    // Deferred in this slice, rendered so the shape of the menu is honest
195	    // about what is coming rather than growing later.
196	    HeaderMenuItem tune;
197	    tune.label   = _L("Tune with the agent");
198	    tune.enabled = false;
199	    rows.push_back(std::move(tune));
200	
201	    HeaderMenuItem reset;
202	    reset.label   = _L("Reset tuning");
203	    reset.enabled = false;
204	    rows.push_back(std::move(reset));
205	    rows.push_back(separator());
206	
207	    HeaderMenuItem settings;
208	    settings.label  = _L("Filament settings…");
209	    settings.invoke = [] { SetupCommands::open_settings_tab(Preset::TYPE_FILAMENT); };
210	    rows.push_back(std::move(settings));
211	
212	    HeaderMenuItem remove;
213	    remove.label            = _L("Remove from this printer");
214	    remove.decoration.danger = true;
215	    remove.keeps_open       = true;
216	    remove.invoke           = [self, spool] {
217	        // Removing the spool forgets a note about a physical reel; it changes
218	        // nothing about the project, which keeps the preset and colour it has.
219	        self->m_host.store->remove(spool.id);
220	        if (self->m_host.store_changed) self->m_host.store_changed();
221	        show_spools(self);
222	    };
223	    rows.push_back(std::move(remove));
224	
225	    menu->replace_items(std::move(rows));
226	}
227	
228	void SpoolMenu::show_other_spool(const Ptr& self)
229	{
230	    auto* menu = self->m_menu.get();
231	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
232	    const auto printer = SetupCommands::current_printer();
233	
234	    // The search field lives above the rows and keeps focus while the result
235	    // list rebuilds under it on every keystroke.
236	    menu->set_header_builder([self](wxWindow* parent) -> wxWindow* {
237	        const auto& palette = self->m_theme.palette(self->m_dark);
238	        auto* field = new wxTextCtrl(parent, wxID_ANY, self->m_search, wxDefaultPosition, wxDefaultSize, wxTE_PROCESS_ENTER);
239	        field->SetHint(_L("Search filaments"));
240	        style_text_field(*field, self->m_theme, palette);
241	        field->SetMinSize(wxSize(-1, field->FromDIP(kFieldHeightDip)));
242	        field->Bind(wxEVT_TEXT, [self](wxCommandEvent& event) {
243	            self->m_search = event.GetString();
244	            // Rebuilding destroys this control, so leave the current event
245	            // first and let the rebuild re-create the field with the text.
246	            // The popup owns the deferral: if it dismisses in between, the
247	            // weak reference drops the call and this controller is gone too.
248	            self->m_owner->CallAfter([self, alive = wxWeakRef<wxWindow>(self->m_menu)] {
249	                if (alive) show_other_spool(self);
250	            });
251	        });
252	        self->m_search_field = field;
253	        return field;
254	    }, 1); // below the back row, as the design places it
255	
256	    std::vector<HeaderMenuItem> rows;
257	    // The title is also the way back one step; without it the only exit from
258	    // this step is dismissing the whole menu. It names the filter in force, so
259	    // a shortened list is never mistaken for the whole list, and going back
260	    // from the generic list lands on the full one rather than leaving the
261	    // menu.
262	    HeaderMenuItem back;
263	    back.label      = self->m_generic_only
264	                        ? wxString::Format(_L("GENERIC PRESETS · FITS %s · %g MM"), printer.nickname.Upper(), printer.nozzle)
265	                        : wxString::Format(_L("OTHER SPOOL · FITS %s · %g MM"), printer.nickname.Upper(), printer.nozzle);
266	    back.icon       = HeaderIcon::Back;
267	    back.keeps_open = true;
268	    back.invoke     = [self] {
269	        if (self->m_generic_only) { self->m_generic_only = false; show_other_spool(self); return; }
270	        self->m_search.clear();
271	        show_spools(self);
272	    };
273	    rows.push_back(std::move(back));
274	
275	    for (const auto& filament : SetupCommands::compatible_filaments()) {
276	        // Whether a preset is generic is a property of the preset, so it is an
277	        // exact test on the vendor the profile declares -- never a text match,
278	        // which would both admit branded presets that happen to read "generic"
279	        // and drop generic ones that do not.
280	        if (self->m_generic_only && filament.vendor != SetupCommands::kGenericVendor) continue;
281	        if (!matches(filament, self->m_search)) continue;
282	        HeaderMenuItem row;
283	        // The step already says every row is generic; repeating the vendor on
284	        // each one would say it a second time and eat the width the name needs.
285	        row.label = filament.vendor.empty() || self->m_generic_only
286	                      ? filament.alias : filament.alias + middot() + filament.vendor;
287	        // A dashed ring: this preset is not a spool yet, and has no colour.
288	        row.decoration.dot = wxColour();
289	        row.keeps_open     = true;
290	        row.invoke         = [self, filament] { show_new_spool(self, filament); };
291	        rows.push_back(std::move(row));
292	    }
293	
294	    // Offered only from the full list: once the filter is on, the title row is
295	    // the affordance, and a row that turns on what is already on says nothing.
296	    if (!self->m_generic_only) {
297	        HeaderMenuItem generic;
298	        generic.separator  = true;
299	        generic.label      = _L("Generic preset…");
300	        generic.keeps_open = true;
301	        generic.invoke     = [self] {
302	            // Generic presets are ordinary compatible presets whose profile
303	            // declares the "Generic" vendor, so this is the same list
304	            // filtered, not a separate source. Whatever was typed still
305	            // applies; nothing is typed on the person's behalf.
306	            self->m_generic_only = true;
307	            show_other_spool(self);
308	        };
309	        rows.push_back(std::move(generic));
310	    }
311	
312	    HeaderMenuItem import;
313	    import.separator = self->m_generic_only; // the rule the generic row carried
314	    import.label  = _L("Import a preset file…");
315	    import.invoke = [] { SetupCommands::import_preset_file(); };
316	    rows.push_back(std::move(import));
317	
318	    menu->replace_items(std::move(rows));
319	    // The rebuild replaced the field, so focus and caret have to be restored
320	    // or every keystroke would land at the start of what was already typed.
321	    if (self->m_search_field) {
322	        self->m_search_field->SetFocus();
323	        self->m_search_field->SetInsertionPointEnd();
324	    }
325	}
326	
327	void SpoolMenu::show_new_spool(const Ptr& self, const SetupCommands::FilamentInfo& preset)
328	{
329	    auto* menu = self->m_menu.get();
330	    if (menu == nullptr) return; // the popup went away; nothing to rebuild
331	    const auto printer = SetupCommands::current_printer();
332	    const bool first   = self->m_new_preset != preset.preset_name;
333	    if (first) {
334	        self->m_new_preset      = preset.preset_name;
335	        self->m_new_material    = preset.material.empty() ? preset.alias : preset.material;
336	        self->m_new_vendor      = preset.vendor;
337	        self->m_new_colour      = wxColour(wxString::FromUTF8(SetupCommands::swatches().front().hex));
338	        self->m_new_name_edited = false;
339	    }
340	    if (!self->m_new_name_edited) {
341	        const wxString word = SetupCommands::colour_word(self->m_new_colour);
342	        self->m_new_name = word.empty() ? preset.alias : word + " " + self->m_new_material;
343	    }
344	
345	    menu->set_header_builder([self, preset](wxWindow* parent) -> wxWindow* {
346	        const auto& palette = self->m_theme.palette(self->m_dark);
347	        auto* panel = new wxPanel(parent);
348	        panel->SetBackgroundColour(palette.surface_raised);
349	        auto* column = new wxBoxSizer(wxVERTICAL);
350	
351	        auto caption = [&](const wxString& text, TextRole role, const wxColour& colour) {
352	            auto* label = new wxStaticText(panel, wxID_ANY, text);
353	            style_label(*label, self->m_theme, role, colour);
354	            return label;
355	        };
356	        column->Add(caption(preset.alias, TextRole::Body, palette.text_primary), 0, wxBOTTOM, panel->FromDIP(8));
357	        column->Add(caption(_L("COLOUR"), TextRole::Metadata, palette.text_secondary), 0, wxBOTTOM, panel->FromDIP(4));
358	
359	        // Twelve swatches on two rows. Each is a small owner-drawn panel
360	        // rather than a button: it carries one value and one selected ring.
361	        const SwatchMetrics& swatch_metrics = self->m_theme.metrics().swatch;
362	        auto* grid = new wxGridSizer(kSwatchesPerRow, panel->FromDIP(4), panel->FromDIP(4));
363	        for (const auto& swatch : SetupCommands::swatches()) {
364	            const wxColour colour(wxString::FromUTF8(swatch.hex));
365	            auto* cell = new wxPanel(panel, wxID_ANY, wxDefaultPosition,
366	                                     panel->FromDIP(wxSize(swatch_metrics.size, swatch_metrics.size)));
367	            cell->SetName(swatch.name);
368	            cell->SetToolTip(_(swatch.name));
369	            cell->SetBackgroundStyle(wxBG_STYLE_PAINT);
370	            cell->Bind(wxEVT_PAINT, [self, cell, colour, palette, radius = swatch_metrics.radius](wxPaintEvent&) {
371	                wxPaintDC dc(cell);
372	                dc.SetBackground(wxBrush(palette.surface_raised));
373	                dc.Clear();
374	                const bool chosen = self->m_new_colour == colour;
375	                dc.SetBrush(wxBrush(colour));
376	                dc.SetPen(wxPen(chosen ? palette.border_strong : palette.border_subtle, chosen ? 2 : 1));
377	                const wxRect box = cell->GetClientRect().Deflate(chosen ? 1 : 2);
378	                dc.DrawRoundedRectangle(box, cell->FromDIP(radius));
379	            });
380	            cell->Bind(wxEVT_LEFT_UP, [self, colour, preset](wxMouseEvent&) {
381	                self->m_new_colour = colour;
382	                self->m_owner->CallAfter([self, preset, alive = wxWeakRef<wxWindow>(self->m_menu)] {
383	                    if (alive) show_new_spool(self, preset);
384	                });
385	            });
386	            grid->Add(cell, 0);
387	        }
388	        column->Add(grid, 0, wxBOTTOM, panel->FromDIP(8));
389	
390	        auto* name = new wxTextCtrl(panel, wxID_ANY, self->m_new_name);
391	        style_text_field(*name, self->m_theme, palette);
392	        name->SetMinSize(wxSize(-1, panel->FromDIP(kFieldHeightDip)));
393	        name->Bind(wxEVT_TEXT, [self](wxCommandEvent& event) {
394	            // Once the person types, the colour no longer rewrites the name.
395	            self->m_new_name        = event.GetString();
396	            self->m_new_name_edited = true;
397	        });
398	        self->m_name_field = name;
399	        column->Add(name, 0, wxEXPAND);
400	
401	        panel->SetSizerAndFit(column);
402	        return panel;
403	    }, 1); // below the back row
404	
405	    std::vector<HeaderMenuItem> rows;
406	    HeaderMenuItem back;
407	    back.label      = wxString::Format(_L("NEW SPOOL FOR %s"), printer.nickname.Upper());
408	    back.icon       = HeaderIcon::Back;
409	    back.keeps_open = true;
410	    back.invoke     = [self] { self->m_new_preset.clear(); show_other_spool(self); };
411	    rows.push_back(std::move(back));
412	
413	    HeaderMenuItem use;
414	    use.label                = _L("Use this spool");
415	    use.separator            = true;
416	    use.decoration.detail    = _L("adds it to the list");
417	    use.decoration.bold      = true;
418	    use.invoke               = [self, printer] {
419	        Workspace::Spool spool;
420	        spool.printer_preset  = printer.preset_name;
421	        spool.filament_preset = self->m_new_preset;
422	        spool.colour          = self->m_new_colour.GetAsString(wxC2S_HTML_SYNTAX).ToStdString();
423	        spool.name            = self->m_new_name.Trim().ToStdString();
424	        spool.brand           = self->m_new_vendor.ToStdString();
425	        if (spool.name.empty()) spool.name = self->m_new_material.ToStdString();
426	        SpoolMenu::select(self, self->m_host.store->add(std::move(spool)));
427	    };
428	    rows.push_back(std::move(use));
429	
430	    menu->replace_items(std::move(rows));
431	    if (self->m_name_field && !self->m_new_name_edited) self->m_name_field->SetInsertionPointEnd();
432	}
