130	    Bind(wxEVT_ENTER_WINDOW, [this](wxMouseEvent&) { m_hover = true; Refresh(); });
131	    Bind(wxEVT_LEAVE_WINDOW, [this](wxMouseEvent&) { m_hover = false; Refresh(); });
132	    Bind(wxEVT_SET_FOCUS, [this](wxFocusEvent& e) { Refresh(); e.Skip(); });
133	    Bind(wxEVT_KILL_FOCUS, [this](wxFocusEvent& e) { m_pressed = false; Refresh(); e.Skip(); });
