137	    });
138	    Bind(wxEVT_LEFT_UP, [this](wxMouseEvent& e) {
139	        const bool invoke = m_pressed && GetClientRect().Contains(e.GetPosition());
140	        const bool on_action = m_row_action != HeaderIcon::None && row_action_rect().Contains(e.GetPosition());
141	        m_pressed = false;
142	        if (HasCapture()) ReleaseMouse();
143	        Refresh();
144	        if (!invoke) return;
145	        if (on_action) invoke_row_action();
146	        else activate(false);
147	    });
148	    // Right-clicking anywhere on the row is the pointer equivalent of the
149	    // row action, for people who do not aim at a glyph that appears on hover.
150	    Bind(wxEVT_RIGHT_UP, [this](wxMouseEvent& e) {
151	        if (m_row_action == HeaderIcon::None) { e.Skip(); return; }
152	        SetFocus();
153	        invoke_row_action();
154	    });
155	    Bind(wxEVT_MOUSE_CAPTURE_LOST, [this](wxMouseCaptureLostEvent&) { m_pressed = false; Refresh(); });
156	    Bind(wxEVT_KEY_DOWN, [this](wxKeyEvent& e) {
157	        if (e.GetKeyCode() == WXK_SPACE) { m_pressed = true; Refresh(); }
158	        else if (e.GetKeyCode() == WXK_RETURN || e.GetKeyCode() == WXK_NUMPAD_ENTER) activate(true);
159	        else e.Skip();
160	    });
161	    Bind(wxEVT_KEY_UP, [this](wxKeyEvent& e) {
162	        if (e.GetKeyCode() == WXK_SPACE && m_pressed) { m_pressed = false; Refresh(); activate(true); }
163	        else e.Skip();
164	    });
