499	void HeaderMenu::build(std::vector<HeaderMenuItem> items)
500	{
501	    const auto palette = m_theme.palette(m_dark);
502	    const PopoverMetrics& popover = m_theme.metrics().popover;
503	    const MenuRowMetrics& menu_row = m_theme.metrics().menu_row;
504	    // A rebuild replaces every row, so drop the old selection rather than
505	    // leaving an index pointing into a destroyed vector.
506	    m_selected = -1;
507	    m_items.clear();
508	    if (auto* old = GetSizer()) {
509	        old->Clear(true);
510	        SetSizer(nullptr, true);
511	    }
512	    m_header = nullptr;
513	
514	    auto* sizer = new wxBoxSizer(wxVERTICAL);
515	    sizer->AddSpacer(FromDIP(popover.padding_y));
516	    int placed_rows = 0;
517	    bool after_row = false; // the row gap sits only between two consecutive rows
518	    auto place_header = [&] {
519	        if (!m_header_builder || m_header != nullptr) return;
520	        m_header = m_header_builder(this);
521	        if (m_header) sizer->Add(m_header,0,wxEXPAND | wxLEFT | wxRIGHT | wxBOTTOM,FromDIP(8));
522	        after_row = false;
523	    };
524	    if (m_header_after_rows == 0) place_header();
525	    for (auto& item : items) {
526	        if (placed_rows == m_header_after_rows) place_header();
527	        if (item.separator) {
528	            auto* line = new wxStaticLine(this);
529	            line->SetForegroundColour(palette.border_subtle);
530	            sizer->Add(line,0,wxEXPAND | wxLEFT | wxRIGHT | wxTOP | wxBOTTOM,FromDIP(menu_row.side_inset));
531	            after_row = false;
532	        }
533	        // A separator-only entry carries no caption of its own.
534	        if (item.title && item.label.empty()) continue;
535	        if (item.title) {
536	            // Eyebrow: a caption, not a row. It takes no focus, no hover, and
537	            // no keyboard stop, so arrow keys skip straight over it.
538	            auto* caption = new wxStaticText(this,wxID_ANY,item.label);
539	            caption->SetFont(m_theme.font(TextRole::Metadata));
540	            caption->SetForegroundColour(palette.text_secondary);
541	            caption->SetBackgroundColour(palette.surface_raised);
542	            sizer->Add(caption,0,wxEXPAND | wxLEFT | wxRIGHT | wxTOP | wxBOTTOM,FromDIP(8));
543	            ++placed_rows;
544	            after_row = false;
545	            continue;
546	        }
547	        auto* button = new HeaderButton(this,m_theme,HeaderStyle::Menu,item.label,item.icon);
548	        button->SetName(item.label);
549	        item.decoration.detail = item.decoration.detail.empty() ? item.detail : item.decoration.detail;
550	        button->set_decoration(item.decoration);
551	        button->set_dark(m_dark);
552	        button->set_row_action(item.row_action);
553	        button->Enable(item.enabled);
554	        if (item.invoke_row_action)
555	            button->Bind(wxEVT_MENU,[this,action=std::move(item.invoke_row_action)](wxCommandEvent&) {
556	                // Like keeps_open rows, this rebuilds the popup's own contents.
557	                // MSVC binds 'this' in a nested lambda's init-capture to the
558	                // enclosing closure, not to HeaderMenu, so name the menu first.
559	                auto* menu = this;
560	                CallAfter([self=wxWeakRef<wxWindow>(menu),action] { if (self) action(); });
561	            });
562	        m_items.push_back(button);
563	        button->Bind(wxEVT_ENTER_WINDOW,[this,index=int(m_items.size()-1)](wxMouseEvent& e) {
564	            if (m_items[index]->IsEnabled()) select_item(index);
565	            e.Skip();
566	        });
567	        if (after_row) sizer->AddSpacer(FromDIP(popover.row_gap));
568	        sizer->Add(button,0,wxEXPAND | wxLEFT | wxRIGHT,FromDIP(menu_row.side_inset));
569	        ++placed_rows;
570	        after_row = true;
571	        button->Bind(wxEVT_BUTTON,[this,owner=wxWeakRef<wxWindow>(GetParent()),invoke=std::move(item.invoke),
572	                                   keeps_open=item.keeps_open](wxCommandEvent&) {
573	            if (!invoke) return;
574	            if (keeps_open) {
575	                // The handler rebuilds this menu's rows, which destroys the
576	                // button currently delivering this event. Defer past it.
577	                // MSVC binds 'this' in a nested lambda's init-capture to the
578	                // enclosing closure, not to HeaderMenu, so name the menu first.
579	                auto* menu = this;
580	                CallAfter([self=wxWeakRef<wxWindow>(menu),invoke] { if (self) invoke(); });
581	                return;
582	            }
583	            close();
584	            if (owner) owner->CallAfter([owner,invoke] { if (owner) invoke(); });
585	        });
586	    }
587	    place_header(); // a step with fewer rows than requested still gets its view
588	    sizer->AddSpacer(FromDIP(popover.padding_y));
589	    SetSizerAndFit(sizer);
590	    // The first build fixes the width; later rebuilds keep it so swapping to
591	    // the search view does not make the popup jump under the pointer.
592	    if (m_width == 0)
593	        m_width = std::clamp(GetSize().x,FromDIP(280),FromDIP(420));
594	    SetSize(wxSize(m_width,GetSize().y));
595	    Layout();
596	#if defined(__WXOSX__) || defined(__WXMSW__)
597	    // Preserve the actual rounded silhouette (and the compositor's popup
598	    // shadow), rather than painting a rounded border into a square window.
599	    auto outline = wxGraphicsRenderer::GetDefaultRenderer()->CreatePath();
600	    outline.AddRoundedRectangle(0,0,GetSize().x,GetSize().y,FromDIP(popover.radius));
601	    SetShape(outline);
602	#endif
603	}
