617	void HeaderMenu::on_key(wxKeyEvent& e)
618	{
619	    const int key = e.GetKeyCode();
620	    if (key == WXK_ESCAPE || key == WXK_TAB) { close(); return; }
621	    if (key == WXK_RETURN || key == WXK_NUMPAD_ENTER || key == WXK_SPACE) {
622	        if (auto* button = selected_item()) {
623	            wxCommandEvent click(wxEVT_BUTTON,button->GetId());
624	            click.SetEventObject(button);
625	            button->ProcessWindowEvent(click);
626	            return;
627	        }
628	        e.Skip();
629	        return;
630	    }
631	    if (key == WXK_RIGHT) {
632	        // The keyboard equivalent of the hover-revealed row action.
633	        if (auto* button = selected_item(); button != nullptr && button->has_row_action()) {
634	            button->invoke_row_action();
635	            return;
636	        }
637	        e.Skip();
638	        return;
639	    }
640	    if (key != WXK_UP && key != WXK_DOWN && key != WXK_HOME && key != WXK_END) { e.Skip(); return; }
641	    if (m_items.empty()) { e.Skip(); return; }
642	    int index = m_selected;
643	    // With no row selected, Down starts before the first and Up wraps back
644	    // from the last -- the same offset trick Home and End use below.
645	    if (index < 0) index = key == WXK_UP ? 0 : -1;
646	    if (key == WXK_HOME) index = -1;
647	    if (key == WXK_END) index = 0;
648	    const int step = key == WXK_UP || key == WXK_END ? -1 : 1;
649	    for (size_t n=0;n<m_items.size();++n) {
650	        index = (index+step+int(m_items.size()))%int(m_items.size());
651	        if (m_items[index]->IsEnabled()) { select_item(index); break; }
652	    }
653	}
