655	void HeaderMenu::open(HeaderButton& anchor)
656	{
657	    m_anchor = &anchor;
658	    anchor.set_open(true);
659	    reposition();
660	    Popup();
661	    Raise();
662	    // Like an owner-drawn list, the popup owns its keyboard selection. Cocoa
663	    // can deliver keys to the popup without assigning focus to a child view.
664	    // A mouse-opened menu highlights nothing until the pointer or an arrow key
665	    // picks a row; a keyboard-opened one starts on the first row so a keyboard
666	    // user has a visible starting point. Arrows work from either state.
667	    if (anchor.activated_by_keyboard())
668	        for (size_t i=0;i<m_items.size();++i) if (m_items[i]->IsEnabled()) { select_item(int(i)); break; }
669	}
