671	void HeaderMenu::reposition()
672	{
673	    if (!m_anchor) return;
674	    Position(m_anchor->ClientToScreen(wxPoint(m_anchor->GetSize().x-GetSize().x,m_anchor->GetSize().y+FromDIP(4))),wxSize(0,0));
675	}
676	
677	void HeaderMenu::select_item(int index)
678	{
679	    if (m_selected >= 0 && m_selected < int(m_items.size())) m_items[m_selected]->set_menu_selected(false);
680	    m_selected = index;
681	    m_items[index]->set_menu_selected(true);
682	}
