684	void HeaderMenu::OnDismiss()
685	{
686	    if (m_closed) return; // Native dismissal and an explicit Escape can coincide.
687	    m_closed = true;
688	    if (m_anchor) { m_anchor->set_open(false); m_anchor->SetFocus(); }
689	    if (m_dismissed) m_dismissed();
690	    Destroy();
691	}
